function dashboardRecommendations(){const done=new Set(state.progress.filter(x=>x.status==='completed').map(x=>Number(x.lesson)));const lesson=state.lessons.find(x=>!done.has(Number(x.id))),assignment=state.assignments.find(x=>!state.assignmentResults.some(r=>String(r.assignment_id)===String(x.id))),game=state.gameResults.length?'scramble':'quiz';const items=[lesson&&{type:'УРОК',title:lesson.title,route:`lesson/${lesson.id}`,icon:'book'},assignment&&{type:'ЗАДАНИЕ',title:assignment.title,route:`game/${encodeURIComponent(assignment.id)}`,icon:'task'},{type:'ИГРА',title:game==='quiz'?'Code Quiz':'Word Scramble',route:`mini/${game}`,icon:'game'}].filter(Boolean);return `<section class="recommend-panel"><div class="section-title"><div><span class="overline">ПЕРСОНАЛЬНАЯ ПОДБОРКА</span><h2>Рекомендуем для тебя</h2></div></div><div>${items.map(x=>`<a href="#${x.route}"><span>${icon(x.icon)}</span><small>${x.type}</small><strong>${esc(x.title)}</strong>${icon('arrow')}</a>`).join('')}</div></section>`}
