function difficultyItems(items,text=item=>item.question_text||String(item)){const sorted=[...items].sort((a,b)=>text(a).length-text(b).length);if(state.gameDifficulty==='hard')sorted.reverse();else if(state.gameDifficulty==='medium')sorted.sort(()=>Math.random()-.5);return sorted.slice(0,gameRoundCount())}
